from modelcrew.workflow import Workflow
base=ROOT/'stage-a-plus'
summary=json.loads((base/'verification-summary.json').read_text(encoding='utf-8'));verification=json.loads((ROOT/summary['report_path']).read_text(encoding='utf-8'))
assert verification['status']=='passed' and file_hash(ROOT/summary['report_path'])==summary['report_sha256']
def junit(name):
    tree=ET.parse(base/'runs'/name).getroot();suites=list(tree.iter('testsuite'))
    return {**{k:sum(int(s.attrib.get(k,0)) for s in suites) for k in ['tests','failures','errors','skipped']},'seconds':sum(float(s.attrib.get('time',0)) for s in suites)}
local=junit('aplus-tests-final.xml');full=junit('full-regression-workspace-temp.xml');failed=junit('full-regression.xml')
assert local['tests']==30 and full['tests']==181 and full['errors']==0 and full['failures']==0 and full['skipped']==0
with Workflow() as w,w.lock('dragon-q1'),w.db.transaction():
    w.db.execute('SET TRANSACTION READ ONLY');task=w.task('dragon-q1')
    contracts=w.db.execute('SELECT version,content,sha256 FROM mc_contracts WHERE task_id=%s ORDER BY version',('dragon-q1',)).fetchall()
    confirmations=w.db.execute("SELECT count(*) AS n FROM mc_events WHERE task_id=%s AND kind IN ('model_approve','result_approve')",('dragon-q1',)).fetchone()['n']
    production={'id':task['id'],'version':task['current_version'],'result_revision':task['result_revision'],'phase':task['phase'],'execution_id':str(task['execution_id']),'model_approved':task['model_approved'],'result_approved':task['result_approved'],'confirmation_count':confirmations,'contract_count':len(contracts),'contract_hashes_valid':all(digest(c['content'])==c['sha256'] for c in contracts)}
assert production['version']==2 and production['result_revision']==2 and production['phase']=='COMPLETED' and production['confirmation_count']==4 and production['contract_count']==2
review=json.loads((base/'mathematical-review.json').read_text(encoding='utf-8'))
criteria=[{'id':'A+1','requirement':'现有小题结构与结论类型','status':'passed','evidence':['cases/bench-dragon.json','method-selection.md']}, {'id':'A+2','requirement':'索引优先、相关原文、前提比较及未选理由','status':'passed','evidence':['sources/read-log.json','cases/bench-dragon-method-selection.json','cases/resource-method-selection.json']},{'id':'A+3','requirement':'形式化、符号/单位/定义域、假设、推导与稳定LaTeX标识','status':'passed_in_A+_draft_scope','evidence':['math/bench-dragon-dossier.json','math/bench-dragon-mathematics.md','math/bench-dragon-fragments.tex','math/resource-dossier.json','math/resource-fragments.tex']},{'id':'A+4','requirement':'区分假设、条件证明与数值观察并绑定实际结果','status':'passed','evidence':['mathematical-review.json',summary['report_path']]},{'id':'A+5','requirement':'不同结构小样例及前提失效反例','status':'passed_in_finite_authored_cases','evidence':['math/resource-mathematics.md','cases/resource-allocation.json','tests/test_aplus.py',summary['report_path']]},{'id':'A+6','requirement':'检查记录、复现入口和图表证据需求','status':'passed','evidence':['validation-plan.json','figure-evidence-plan.json','scripts/verify_aplus_baseline.py','verification-summary.json']}]
report={'date':datetime.now().astimezone().isoformat(),'stage':'A+','status':'implemented_and_verified','engineering_acceptance':'passed_in_declared_A+_scope','user_acceptance':'not_recorded_for_A+','criteria':criteria,'verification':{'direct_math_and_numeric_checks':49,'aplus_tests':local,'full_regression':full,'first_full_attempt':{'results':failed,'failure_reason':'37 tests could not create system temp fixtures due to Windows PermissionError; no algorithm failures were hidden.','resolution':'Retried with a fresh --basetemp within workspace.','evidence':'runs/full-regression.xml'},'summary':'verification-summary.json','report':summary['report_path']},'production_task_read_only_recheck':production,'historical_B_status':json.loads((ROOT/'stage-b/progress.json').read_text(encoding='utf-8'))['status'],'historical_C_status':json.loads((ROOT/'stage-c/progress.json').read_text(encoding='utf-8'))['status'],'new_model_API_calls':0,'new_contest_full_solver_executions':0,'new_synthetic_LP_solves_per_verifier_run':3,'reference_diagnostics':'Head/rod/velocity checks and reference finite-difference/refinement calls are newly performed diagnostics, not new LLM-generated code execution.','latex_export':{'source_files':2,'equations':15,'compiled':False,'rendered':False,'owner':'C+'},'known_limits':verification['limitations']+['A+ chooses from finite declared structures; no general natural-language problem classifier or autonomous algorithm router.','B+ formal version contracts and C+ real compilation/rendering remain unimplemented.','Existing fixed-fixture Excel exception is preserved; no restoration effort restarted.'],'next_scope':'B+ mathematical package/version handoff; no B+ implementation or new model/result approvals performed.'}
files=[p for p in base.rglob('*') if p.is_file() and 'runs' not in p.relative_to(base).parts]
report['artifact_sha256']={str(p.relative_to(ROOT)):file_hash(p) for p in files if p.name!='acceptance.json'}
report['code_sha256']={str(p.relative_to(ROOT)):file_hash(p) for p in [ROOT/'modelcrew/aplus.py',ROOT/'scripts/prepare_aplus_baseline.py',ROOT/'scripts/verify_aplus_baseline.py',ROOT/'tests/test_aplus.py']}
