(base/'progress.json').write_text(json.dumps(progress,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
report['artifact_sha256']['stage-a-plus/progress.json']=file_hash(base/'progress.json')
(base/'acceptance.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'stage':'A+','status':report['status'],'direct_checks':49,'aplus_tests':local,'full_tests':full,'production_task':production},ensure_ascii=False,indent=2))
